INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (19, 'content_entry', 7, 1, 'fr', 'published', 1, NULL, NULL, NULL, 'Initial', 'Article de démonstration sur la couche SEO native.', NULL, '{"schema_version": 1, "entry_id": 7, "language_code": "fr", "content": {"title": "SEO, multilingue et multi-site", "slug": "seo-multisite", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Le CMS repose sur des révisions comme source de vérité et sur des projections publiées pour les routes, les métadonnées SEO, la recherche, les redirections et les tombstones. Cette architecture permet un runtime léger et des signaux SEO cohérents dès la publication."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "Équipe DEC CMS"}, "seo": {"meta_title": "SEO multilingue et multi-site dans un CMS éditorial", "meta_description": "Article de démonstration sur les projections publiées, les routes canoniques, le hreflang, la recherche native et le SEO multilingue.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Le CMS repose sur des révisions comme source de vérité et sur des projections publiées pour les routes, les métadonnées SEO, la recherche, les redirections et les tombstones. Cette architecture permet un runtime léger et des signaux SEO cohérents dès la publication."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', 'd484f5229624b19c30b92eba9ace94e30404be4da467392508c337baa7974178', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09 06:14:27', '2026-05-09 06:14:27');
INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (20, 'content_entry', 7, 2, 'en', 'published', 1, NULL, NULL, NULL, 'Initial', 'Demonstration article about the native SEO layer.', NULL, '{"schema_version": 1, "entry_id": 7, "language_code": "en", "content": {"title": "SEO, multilingual and multi-site", "slug": "seo-multisite", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "The CMS uses revisions as the source of truth and published projections for routes, SEO metadata, search, redirects and tombstones. This architecture keeps the public runtime lightweight and SEO signals coherent as soon as content is published."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "DEC CMS team"}, "seo": {"meta_title": "Multilingual and multi-site SEO in an editorial CMS", "meta_description": "Demonstration article about published projections, canonical routes, hreflang, native search and multilingual SEO.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "The CMS uses revisions as the source of truth and published projections for routes, SEO metadata, search, redirects and tombstones. This architecture keeps the public runtime lightweight and SEO signals coherent as soon as content is published."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', 'ec910e7caebf66dd039bcbb27b52f1a7e535d890ed2cd13785236216a92a10e7', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09 06:14:27', '2026-05-09 06:14:27');
INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (21, 'content_entry', 7, 3, 'de', 'published', 1, NULL, NULL, NULL, 'Initial', 'Demonstrationsartikel über die native SEO-Schicht.', NULL, '{"schema_version": 1, "entry_id": 7, "language_code": "de", "content": {"title": "SEO, mehrsprachig und multisite", "slug": "seo-multisite", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Das CMS nutzt Revisionen als Quelle der Wahrheit und veröffentlichte Projektionen für Routen, SEO-Metadaten, Suche, Weiterleitungen und Tombstones. Diese Architektur hält das öffentliche Runtime leicht und SEO-Signale ab der Veröffentlichung kohärent."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "DEC CMS Team"}, "seo": {"meta_title": "Mehrsprachiges und multisite SEO in einem Redaktions-CMS", "meta_description": "Demonstrationsartikel über veröffentlichte Projektionen, kanonische Routen, hreflang, native Suche und mehrsprachiges SEO.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Das CMS nutzt Revisionen als Quelle der Wahrheit und veröffentlichte Projektionen für Routen, SEO-Metadaten, Suche, Weiterleitungen und Tombstones. Diese Architektur hält das öffentliche Runtime leicht und SEO-Signale ab der Veröffentlichung kohärent."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', '2a2479a9d90ef9cc45654f0831d6df5db64243c5e450f014ce2443052ae673e4', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09 06:14:27', '2026-05-09 06:14:27');
INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (22, 'content_entry', 8, 1, 'fr', 'published', 1, NULL, NULL, NULL, 'Initial', 'Pourquoi le front public doit lire des snapshots stables.', NULL, '{"schema_version": 1, "entry_id": 8, "language_code": "fr", "content": {"title": "Runtime léger et projections publiques", "slug": "runtime-leger", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Un runtime public performant évite de recalculer les relations éditoriales à chaque requête. Les snapshots publiés deviennent le contrat de lecture : route, SEO, blocs et recherche sont déjà prêts."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "Équipe DEC CMS"}, "seo": {"meta_title": "Runtime léger et snapshots publics", "meta_description": "Comprendre comment les projections publiques rendent le CMS plus rapide, stable et facile à mettre en cache.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Un runtime public performant évite de recalculer les relations éditoriales à chaque requête. Les snapshots publiés deviennent le contrat de lecture : route, SEO, blocs et recherche sont déjà prêts."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', '0f106f5f99232c9951854d1370a49f6ae7abad25d233f108aa35c5ba75a20372', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09 06:14:27', '2026-05-09 06:14:27');
INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (23, 'content_entry', 8, 2, 'en', 'published', 1, NULL, NULL, NULL, 'Initial', 'Why the public front should read stable snapshots.', NULL, '{"schema_version": 1, "entry_id": 8, "language_code": "en", "content": {"title": "Lightweight runtime and public projections", "slug": "runtime-leger", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "A fast public runtime avoids recalculating editorial relations on every request. Published snapshots become the read contract: route, SEO, blocks and search are ready."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "DEC CMS team"}, "seo": {"meta_title": "Lightweight runtime and public snapshots", "meta_description": "Understand how public projections make the CMS faster, more stable and easier to cache.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "A fast public runtime avoids recalculating editorial relations on every request. Published snapshots become the read contract: route, SEO, blocks and search are ready."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', 'f500f4dd78a8b95d09f49ff435edce5681b1c6a97bb3c2b045e9bef1cf4f1a65', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09 06:14:27', '2026-05-09 06:14:27');
INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (24, 'content_entry', 8, 3, 'de', 'published', 1, NULL, NULL, NULL, 'Initial', 'Warum das öffentliche Frontend stabile Snapshots lesen sollte.', NULL, '{"schema_version": 1, "entry_id": 8, "language_code": "de", "content": {"title": "Leichtes Runtime und öffentliche Projektionen", "slug": "runtime-leger", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Ein schnelles öffentliches Runtime vermeidet es, redaktionelle Beziehungen bei jeder Anfrage neu zu berechnen. Veröffentlichte Snapshots werden zum Lesevertrag: Route, SEO, Blöcke und Suche sind vorbereitet."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "DEC CMS Team"}, "seo": {"meta_title": "Leichtes Runtime und öffentliche Snapshots", "meta_description": "Wie öffentliche Projektionen das CMS schneller, stabiler und cache-freundlicher machen.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Ein schnelles öffentliches Runtime vermeidet es, redaktionelle Beziehungen bei jeder Anfrage neu zu berechnen. Veröffentlichte Snapshots werden zum Lesevertrag: Route, SEO, Blöcke und Suche sind vorbereitet."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', '2b689bcbfc802d8d3cb565a716a849bc0ffd5e8fad3c31292f2b9c46a59059e8', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09 06:14:27', '2026-05-09 06:14:27');
INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (25, 'content_entry', 9, 1, 'fr', 'published', 1, NULL, NULL, NULL, 'Initial', 'Markdown, HTML, médias et hero dans un modèle commun.', NULL, '{"schema_version": 1, "entry_id": 9, "language_code": "fr", "content": {"title": "Éditeur par blocs : garder le contenu lisible", "slug": "editeur-blocs", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Le système de blocs doit rester compréhensible : chaque bloc porte un type, des données, un ordre et des paramètres simples. Cette approche facilite le rendu desktop, mobile et SEO."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "Équipe DEC CMS"}, "seo": {"meta_title": "Éditeur par blocs natif pour CMS", "meta_description": "Structurer les contenus avec des blocs Markdown, HTML, médias, iframe et hero sans alourdir le runtime public.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Le système de blocs doit rester compréhensible : chaque bloc porte un type, des données, un ordre et des paramètres simples. Cette approche facilite le rendu desktop, mobile et SEO."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', '5206f646d70f0e55eb3c0e79afbd8813402a31a024bcaa52d13e8469404f7d89', NULL, 1, 1, 1, '