INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (26, 'content_entry', 9, 2, 'en', 'published', 1, NULL, NULL, NULL, 'Initial', 'Markdown, HTML, media and hero blocks in one model.', NULL, '{"schema_version": 1, "entry_id": 9, "language_code": "en", "content": {"title": "Block editor: keeping content readable", "slug": "editeur-blocs", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "The block system should stay understandable: each block carries a type, data, order and simple settings. This approach supports desktop, mobile and SEO rendering."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "DEC CMS team"}, "seo": {"meta_title": "Native block editor for CMS", "meta_description": "Structure content with Markdown, HTML, media, iframe and hero blocks without weighing down the public runtime.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "The block system should stay understandable: each block carries a type, data, order and simple settings. This approach supports desktop, mobile and SEO rendering."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', '7ff2a73e89c96c11a82fb78e1f8f5847993facffa61e085e0bb799448e42452b', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09 06:14:27', '2026-05-