INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (28, 'content_entry', 10, 1, 'fr', 'published', 1, NULL, NULL, NULL, 'Initial', 'Différencier classement principal et mots-clés transversaux.', NULL, '{"schema_version": 1, "entry_id": 10, "language_code": "fr", "content": {"title": "Taxonomies éditoriales : catégories et tags", "slug": "taxonomies-editoriales", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Les catégories servent de classement éditorial stable. Les tags permettent des croisements plus souples. L’index des articles peut alors proposer des filtres utiles sans configuration manuelle."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "Équipe DEC CMS"}, "seo": {"meta_title": "Taxonomies éditoriales dans un CMS", "meta_description": "Utiliser catégories et tags pour filtrer automatiquement les articles et structurer une navigation éditoriale claire.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Les catégories servent de classement éditorial stable. Les tags permettent des croisements plus souples. L’index des articles peut alors proposer des filtres utiles sans configuration manuelle."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', '3ca4b0645cb8e9143847450dda9af87067