INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (29, 'content_entry', 10, 2, 'en', 'published', 1, NULL, NULL, NULL, 'Initial', 'Separate primary classification from transversal keywords.', NULL, '{"schema_version": 1, "entry_id": 10, "language_code": "en", "content": {"title": "Editorial taxonomies: categories and tags", "slug": "taxonomies-editoriales", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Categories provide stable editorial classification. Tags allow more flexible cross-links. The article index can then provide useful filters without manual configuration."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "DEC CMS team"}, "seo": {"meta_title": "Editorial taxonomies in a CMS", "meta_description": "Use categories and tags to automatically filter articles and build clear editorial navigation.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Categories provide stable editorial classification. Tags allow more flexible cross-links. The article index can then provide useful filters without manual configuration."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', 'f5bcd00c84b7fc1a48c39290c81d5b7239409c87c0847c8b445a7799fe8214be', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09 06:14:27', '2026-05-09 06:14:27');
INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (30, 'content_entry', 10, 3, 'de', 'published', 1, NULL, NULL, NULL, 'Initial', 'Hauptklassifikation und Querverweise trennen.', NULL, '{"schema_version": 1, "entry_id": 10, "language_code": "de", "content": {"title": "Redaktionelle Taxonomien: Kategorien und Tags", "slug": "taxonomies-editoriales", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Kategorien bilden eine stabile redaktionelle Klassifikation. Tags ermöglichen flexiblere Querverbindungen. Der Artikelindex kann dadurch nützliche Filter ohne manuelle Konfiguration anbieten."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "DEC CMS Team"}, "seo": {"meta_title": "Redaktionelle Taxonomien in einem CMS", "meta_description": "Kategorien und Tags nutzen, um Artikel automatisch zu filtern und klare redaktionelle Navigation zu schaffen.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Kategorien bilden eine stabile redaktionelle Klassifikation. Tags ermöglichen flexiblere Querverbindungen. Der Artikelindex kann dadurch nützliche Filter ohne manuelle Konfiguration anbieten."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', '01801ae784ef5e5a61da9b7e8a6493aeaf829a12a8e12d701930eda91337264d', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09 06:14:27', '2026-05-09 06:14:27');
INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (31, 'content_entry', 11, 1, 'fr', 'published', 1, NULL, NULL, NULL, 'Initial', 'Un menu doit pointer vers une intention, pas vers un contenu isolé.', NULL, '{"schema_version": 1, "entry_id": 11, "language_code": "fr", "content": {"title": "Routes propres et menu éditorial", "slug": "routes-propres", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Un lien de menu appelé Articles doit mener à une collection. Les articles individuels restent accessibles par leurs routes propres, tandis que l’index porte le rôle de page d’entrée éditoriale."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "Équipe DEC CMS"}, "seo": {"meta_title": "Routes propres et menus éditoriaux", "meta_description": "Pourquoi un menu Articles doit pointer vers une page d’index filtrable plutôt que vers un article précis.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Un lien de menu appelé Articles doit mener à une collection. Les articles individuels restent accessibles par leurs routes propres, tandis que l’index porte le rôle de page d’entrée éditoriale."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', '3398b051749e80ba5217c4b0ba62865c9fb530b1792362a4ebb995262c5f72b4', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09 06:14:27', '2026-05-09 06:14:27');
INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (32, 'content_entry', 11, 2, 'en', 'published', 1, NULL, NULL, NULL, 'Initial', 'A menu should point to an intent, not an isolated content item.', NULL, '{"schema_version": 1, "entry_id": 11, "language_code": "en", "content": {"title": "Clean routes and editorial menu", "slug": "routes-propres", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "A menu link named Articles should lead to a collection. Individual articles keep their own clean routes, while the index acts as the editorial entry page."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "DEC CMS team"}, "seo": {"meta_title": "Clean routes and editorial menus", "meta_description": "Why an Articles menu should point to a filterable index page rather than to one specific article.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "A menu link named Articles should lead to a collection. Individual articles keep their own clean routes, while the index acts as the editorial entry page."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', '3ab7b14948f694bceb167795d04894afb534cfa79efc0b296a18d01f3ad68e89', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09 06:14:27', '2026-05-09 06:14:27');
INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (33, 'content_entry', 11, 3, 'de', 'published', 1, NULL, NULL, NULL, 'Initial', 'Ein Menü sollte auf eine Absicht zeigen, nicht auf einen Einzelinhalt.', NULL, '{"schema_version": 1, "entry_id": 11, "language_code": "de", "content": {"title": "Saubere Routen und redaktionelles Menü", "slug": "routes-propres", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Ein Menülink namens Artikel sollte zu einer Sammlung führen. Einzelne Artikel behalten ihre eigenen sauberen Routen, während der Index die redaktionelle Einstiegsseite bildet."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "DEC CMS Team"}, "seo": {"meta_title": "Saubere Routen und redaktionelle Menüs", "meta_description": "Warum ein Artikel-Menü auf eine filterbare Indexseite statt auf einen einzelnen Artikel zeigen sollte.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Ein Menülink namens Artikel sollte zu einer Sammlung führen. Einzelne Artikel behalten ihre eigenen sauberen Routen, während der Index die redaktionelle Einstiegsseite bildet."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', '4d6f6058e9a1e7540c0fb50cfdc6a16ff3631a7b4cbada74b0e6a660bed45593', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09 06:14:27', '2026-05-09 06:14:27');
INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (34, 'content_entry', 12, 1, 'fr', 'published', 1, NULL, NULL, NULL, 'Initial', 'Les signaux SEO doivent être produits par le moteur.', NULL, '{"schema_version": 1, "entry_id": 12, "language_code": "fr", "content": {"title": "SEO technique : canonical, hreflang et JSON-LD", "slug": "seo-jsonld", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Le CMS doit générer automatiquement canonical, hreflang, Open Graph, sitemap et JSON-LD à partir des données publiées. L’éditeur reste concentré sur la qualité du contenu."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "Équipe DEC CMS"}, "seo": {"meta_title": "SEO technique natif dans un CMS", "meta_description": "Canonical, hreflang, Open Graph, sitemap et JSON-LD générés depuis les projections publiées du CMS.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "Le CMS doit générer automatiquement canonical, hreflang, Open Graph, sitemap et JSON-LD à partir des données publiées. L’éditeur reste concentré sur la qualité du contenu."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', 'a7e9a5a9fa388bb3c425c4ae3e1505cd5cdb51e31d92449617aa91351775f511', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09