INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (35, 'content_entry', 12, 2, 'en', 'published', 1, NULL, NULL, NULL, 'Initial', 'SEO signals should be produced by the engine.', NULL, '{"schema_version": 1, "entry_id": 12, "language_code": "en", "content": {"title": "Technical SEO: canonical, hreflang and JSON-LD", "slug": "seo-jsonld", "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "The CMS should automatically generate canonical URLs, hreflang, Open Graph, sitemap and JSON-LD from published data. Editors can focus on content quality."}, "sort_order": 0}]}, "settings": {}, "fields": {"author_name": "DEC CMS team"}, "seo": {"meta_title": "Native technical SEO in a CMS", "meta_description": "Canonical URLs, hreflang, Open Graph, sitemap and JSON-LD generated from CMS public projections.", "meta_robots": "index,follow"}, "blocks": [{"id": "article_body_01", "type": "markdown", "enabled": true, "editorial_status": "published", "label": "Corps de l’article", "css_class": "", "anchor": "", "data": {"text": "The CMS should automatically generate canonical URLs, hreflang, Open Graph, sitemap and JSON-LD from published data. Editors can focus on content quality."}, "sort_order": 0}], "audit": {"created_by_iam_user_id": 1, "updated_by_iam_user_id": 1, "published_by_iam_user_id": 1}}', 'e9b7b4483e6034b8edcc94956d776944bf437d79f7fa992ba0885fcec61a4079', NULL, 1, 1, 1, '2026-05-09 06:14:27', '2026-05-09 06:14:27', '2026-05-09 06:14:27');
