INSERT INTO "revisions" ("id", "resource_type", "resource_id", "revision_number", "language_code", "workflow_status", "document_schema_version", "base_revision_id", "source_published_revision_id", "created_from_event", "revision_label", "summary", "change_notes", "document_json", "checksum_sha256", "scheduled_for", "created_by_iam_user_id", "updated_by_iam_user_id", "published_by_iam_user_id", "created_at", "updated_at", "published_at") VALUES (60, 'content_entry', 1, 9, 'fr', 'superseded', 1, NULL, NULL, NULL, 'Working draft', 'Découvrez un CMS éditorial SEO-first avec routes propres, canonical, hreflang, sitemap, robots.txt, Open Graph, JSON-LD, recherche native et runtime léger.', '', '{
    "schema_version": 2,
    "entry_id": 1,
    "content_type": "page",
    "language_code": "fr",
    "content": {
        "title": "Accueil",
        "slug": "home",
        "blocks": [
            {
                "id": "home_hero_01",
                "type": "hero",
                "enabled": true,
                "editorial_status": "published",
                "label": "Hero accueil",
                "css_class": "",
                "anchor": "",
                "data": {
                    "eyebrow": "Publication propre, rapide et multilingue",
                    "title": "Accueil",
                    "lead": "Un front public de référence pour un CMS éditorial SEO-first.",
                    "heading_level": "h1",
                    "image_media_id": 0,
                    "image_src": "",
                    "image_srcset": "",
                    "image_sizes": "",
                    "image_alt": "",
                    "image_width": 1280,
                    "image_height": 853,
                    "image_mime_type": "",
                    "image_loading": "eager",
                    "layout": "split",
                    "buttons": [
                        {
                            "label": "Découvrir le CMS",
                            "url": "/mod/articles",
                            "style": "primary",
                            "target": "_self"
                        },
                        {
                            "label": "Contact",
                            "url": "/mod/contact",
                            "style": "ghost",
                            "target": "_self"
                        }
                    ]
                },
                "sort_order": 0
            },
            {
                "id": "home_cards_01",
                "type": "columns",
                "enabled": true,
                "editorial_status": "published",
                "label": "Cartes forces",
                "css_class": "section",
                "anchor": "",
                "data": {
                    "layout": "cards-3",
                    "columns": [
                        {
                            "width": "auto",
                            "blocks": [
                                {
                                    "id": "home_card_1",
                                    "type": "html",
                                    "enabled": true,
                                    "editorial_status": "published",
                                    "label": "SEO-first",
                                    "css_class": "card feature-card",
                                    "anchor": "",
                                    "data": {
                                        "html": "<span class=\"feature-card__icon\" aria-hidden=\"true\">↝</span><h2>SEO-first</h2><p>Canonical, hreflang, Open Graph, meta description et routes publiées propres.</p>"
                                    },
                                    "sort_order": 0
                                }
                            ]
                        },
                        {
                            "width": "auto",
                            "blocks": [
                                {
                                    "id": "home_card_2",
                                    "type": "html",
                                    "enabled": true,
                                    "editorial_status": "published",
                                    "label": "Multilingue",
                                    "css_class": "card feature-card",
                                    "anchor": "",
                                    "data": {
                                        "html": "<span class=\"feature-card__icon\" aria-hidden=\"true\">文</span><h2>Multilingue</h2><p>Références en français, anglais et allemand avec navigation adaptée à la langue.</p>"
                                    },
                                    "sort_order": 0
                                }
                            ]
                        },
                        {
                            "width": "auto",
                            "blocks": [
                                {
                                    "id": "home_card_3",
                                    "type": "html",
                                    "enabled": true,
                                    "editorial_status": "published",
                                    "label": "Runtime léger",
                                    "css_class": "card feature-card",
                                    "anchor": "",
                                    "data": {
                                        "html": "<span class=\"feature-card__icon\" aria-hidden=\"true\">⚡</span><h2>Runtime léger</h2><p>HTML natif, templates Twig, CSS compact et couche publique minimale.</p>"
                                    },
                                    "sort_order": 0
                                }
                            ]
                        }
                    ]
                },
                "sort_order": 1
            },
            {
                "id": "home_split_01",
                "type": "html",
