    "schema_version": 2,
    "entry_id": 1,
    "content_type": "page",
    "language_code": "fr",
    "content": {
        "title": "Accueil",
        "slug": "home",
        "blocks": [
            {
                "id": "home_hero_01",
                "type": "hero",
                "enabled": true,
                "editorial_status": "published",
                "label": "Hero accueil",
                "css_class": "",
                "anchor": "",
                "data": {
                    "eyebrow": "Publication propre, rapide et multilingue",
                    "title": "Accueil",
                    "lead": "Un front public de référence pour un CMS éditorial SEO-first.",
                    "heading_level": "h1",
                    "image_media_id": 4,
                    "image_src": "/mod/storage/media/public/1/2026/05/variants/cms-hero-1280-9ff7381c-hero_960.webp",
