                                    "data": {
                                        "html": "<span class=\"feature-card__icon\" aria-hidden=\"true\">↝</span><h2>SEO-first</h2><p>Canonical, hreflang, Open Graph, meta description et routes publiées propres.</p>"
                                    },
                                    "sort_order": 0
                                }
