INSERT INTO "public_content_snapshots" ("id", "site_id", "language_code", "resource_type", "resource_id", "route_path", "title", "slug", "blocks_json", "block_count", "document_json", "seo_json", "source_published_revision_id", "source_revision_checksum_sha256", "published_at", "projected_at") VALUES (222, 1, 'en', 'content_entry', 9, '/articles/editeur-blocs', 'Block editor: keeping content readable', 'editeur-blocs', '[{"id":"article_body_01","type":"markdown","enabled":true,"editorial_status":"published","label":"Corps de l’article","css_class":"","anchor":"","data":{"text":"The block system should stay understandable: each block carries a type, data, order and simple settings. This approach supports desktop, mobile and SEO rendering."},"sort_order":0}]', 1, '{"schema_version":1,"entry_id":9,"language_code":"en","content":{"title":"Block editor: keeping content readable","slug":"editeur-blocs","blocks":[{"id":"article_body_01","type":"markdown","enabled":true,"editorial_status":"published","label":"Corps de l’article","css_class":"","anchor":"","data":{"text":"The block system should stay understandable: each block carries a type, data, order and simple settings. This approach supports desktop, mobile and SEO rendering."},"sort_order":0}]},"settings":[],"fields":{"author_name":"DEC CMS team"},"seo":{"meta_title":"Native block editor for CMS","meta_description":"Structure content with Markdown, HTML, media, iframe and hero blocks without weighing down the public runtime.","meta_robots":"index,follow"},"blocks":[{"id":"article_body_01","type":"markdown","enabled":true,"editorial_status":"published","label":"Corps de l’article","css_class":"","anchor":"","data":{"text":"The block system should stay understandable: each block carries a type, data, order and simple settings. This approach supports desktop, mobile and SEO rendering."},"sort_order":0}],"audit":{"created_by_iam_user_id":1,"updated_by_iam_user_id":1,"published_by_iam_user_id":1}}', '{"resource_type":"cont