-- Synchronise le snapshot SEO seedé avec seo_metadata, source lue par le front et l'API publique.
UPDATE public_content_snapshots
SET seo_json = json_object(
    'resource_type', sm.resource_type,
    'resource_id', sm.resource_id,
    'language_code', sm.language_code,
    'meta_title', sm.meta_title,
    'meta_description', sm.meta_description,
    'canonical_url', sm.canonical_url,
    'meta_robots', sm.meta_robots,
    'json_ld', sm.json_ld,
    'seo_score', sm.seo_score,
    'og_title', sm.og_title,
    'og_description', sm.og_description,
    'og_image_media_id', sm.og_image_media_id,
    'twitter_title', sm.twitter_title,
    'twitter_description', sm.twitter_description,
    'twitter_image_media_id', sm.twitter_image_media_id,
    'hreflang_code', sm.hreflang_code,
    'source', NULL,
    'is_indexable', CASE WHEN lower(COALESCE(sm.meta_robots, 'index,follow')) LIKE '%noindex%' THEN json('false') ELSE json('true') END,
    'issues', json('[]')
)
FROM seo_metadata sm
WHERE sm.site_id = public_content_snapshots.site_id
  AND sm.resource_type = public_content_snapshots.resource_type
  AND sm.resource_id = public_content_snapshots.resource_id
  AND sm.language_code = public_content_snapshots.language_code
  AND sm.source_published_revision_id = public_content_snapshots.source_published_revision_id
  AND sm.source_revision_checksum_sha256 = public_content_snapshots.source_revision_checksum_sha256;

